  --bg4:#232836;
  --border:#2a3040;
  --accent:#9b6cf0;
  --accent2:#cdb6ff;
  --text:#eef1f7;
  --text2:#a2abbd;
  --text3:#6c7589;
  --green:#4caf7d;
  --blue:#cdb6ff;
  --r8:8px; --r12:12px; --r16:16px; --r20:20px;
  --sidebar:260px;
  --header:52px;
}

html,body{height:100%;overflow:hidden}
body{background:var(--bg);color:var(--text);font-family:-apple-system,'SF Pro Text','Segoe UI',Roboto,sans-serif;font-size:16px;display:flex;flex-direction:column;position:fixed;inset:0;touch-action:manipulation}

/* ═══════ HEADER ═══════ */
#app-header{
  height:var(--header);background:var(--bg);
  border-bottom:1px solid var(--border);
  display:flex;align-items:center;padding:0 14px;gap:10px;
  flex-shrink:0;z-index:10;
}
.hbtn{width:40px;height:40px;border-radius:var(--r8);background:none;border:none;color:var(--text2);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:18px;transition:background .15s}
.hbtn:hover{background:var(--bg3)}
.htitle{flex:1;font-size:16.5px;font-weight:600;color:var(--text);text-align:center;letter-spacing:.01em}
.haction{display:flex;gap:4px}

/* ═══════ LAYOUT ═══════ */
#layout{flex:1;display:flex;overflow:hidden;position:relative}

/* ═══════ SIDEBAR ═══════ */
#sidebar{
  width:var(--sidebar);background:var(--bg);
  border-right:1px solid var(--border);
  display:flex;flex-direction:column;
  flex-shrink:0;overflow:hidden;
  position:absolute;top:0;left:0;bottom:0;
  z-index:50;transform:translateX(-100%);
  transition:transform .28s cubic-bezier(.4,0,.2,1);
}
#sidebar.open{transform:none}
#sb-overlay{position:absolute;inset:0;background:rgba(0,0,0,.6);z-index:40;display:none;backdrop-filter:blur(2px)}
#sb-overlay.show{display:block}

.sb-top{padding:20px 16px 12px;border-bottom:1px solid var(--border)}
.sb-logo{
  width:48px;height:48px;
  animation:pulse-glow 4s ease-in-out infinite;
  margin-bottom:10px
}
@keyframes pulse-glow{
  0%,100%{filter:drop-shadow(0 0 4px rgba(155,108,240,.2))}
  50%{filter:drop-shadow(0 0 14px rgba(155,108,240,.55))}
}
.sb-brand{font-size:24px;font-weight:800;color:var(--text);letter-spacing:.06em}

.sb-nav{flex:1;overflow-y:auto;padding:10px 10px}
.sb-item{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:var(--r12);cursor:pointer;color:var(--text2);font-size:16px;transition:all .15s;margin-bottom:2px}
.sb-item:hover{background:var(--bg3);color:var(--text)}
.sb-item.active{background:var(--bg3);color:var(--text)}
.sb-item.accent{color:var(--accent)}
.sb-item.accent:hover{background:rgba(155,108,240,.08)}
.sb-icon{font-size:17px;flex-shrink:0;width:22px;text-align:center}
.sb-label{font-weight:500}
.sb-sep{height:1px;background:var(--border);margin:8px 0}
.sb-section{font-size:13.5px;font-weight:600;color:var(--text3);padding:6px 12px 4px;text-transform:uppercase;letter-spacing:.07em;display:flex;align-items:center;justify-content:space-between}
.sb-sync-btn{background:none;border:none;color:var(--text3);cursor:pointer;padding:2px 4px;display:flex;align-items:center;border-radius:6px}
.sb-sync-btn:active{background:var(--border);color:var(--text)}
.sb-sync-btn svg{width:14px;height:14px}
.sb-sync-btn.spinning svg{animation:nps-spin .7s linear infinite}
@keyframes nps-spin{to{transform:rotate(360deg)}}
.sb-recent{padding:7px 12px;border-radius:var(--r8);cursor:pointer;color:var(--text2);font-size:15.5px;transition:all .15s;margin-bottom:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sb-recent-list{padding:7px 12px}
.sb-recent{-webkit-user-select:none;user-select:none;transition:background .15s,color .15s}
@media (hover:hover){.sb-recent:hover{background:var(--bg3);color:var(--text)}}
.sb-recent:active{background:var(--bg3)}
.sb-recent.active{background:rgba(var(--accent-rgb,239,120,74),0.18);color:var(--accent);font-weight:600;border-left:3px solid var(--accent);}
@media (hover:hover){.sb-recent.active:hover{background:rgba(var(--accent-rgb,239,120,74),0.25);}}
.sb-recent.active:active{background:rgba(var(--accent-rgb,239,120,74),0.18);}
.conv-menu-item{display:flex;align-items:center;gap:10px;width:100%;background:none;border:none;color:var(--text);font-size:15.5px;padding:9px 12px;border-radius:8px;cursor:pointer;text-align:left;}
.conv-menu-item:hover{background:var(--bg3);}

.sb-foot{padding:12px 12px;border-top:1px solid var(--border);display:flex;align-items:center;justify-content:space-between}
.sb-user{display:flex;align-items:center;gap:10px;flex:1;min-width:0}
