.eg-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;width:100%;max-width:320px;margin-top:4px}
.eg-card{background:var(--bg2);border:1px solid var(--border);border-radius:var(--r12);padding:12px;cursor:pointer;text-align:left;transition:all .15s}
.eg-card:hover{border-color:var(--accent);background:var(--bg3)}
.eg-icon{margin-bottom:6px;color:var(--accent);display:flex}
.eg-title{font-size:13.5px;font-weight:600;color:var(--text);margin-bottom:3px}
.eg-sub{font-size:13px;color:var(--text2);line-height:1.5}

/* MESSAGES */
.msg-group{display:flex;flex-direction:column;gap:4px}
.msg-row{display:flex;gap:10px;align-items:flex-start}
.msg-row.user{flex-direction:row-reverse}
.msg-av{width:30px;height:30px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:13.5px;font-weight:700}
.msg-av.bot{
  background:var(--bg2);border:1px solid var(--border);
  overflow:hidden;padding:2px;
}
.msg-av.bot svg{width:26px;height:26px}
.msg-av.user{background:var(--bg3);border:1px solid var(--border);color:var(--text2)}
.msg-bubble{
  max-width:78%;padding:10px 13px;border-radius:var(--r16);
  font-size:15.5px;line-height:1.65;word-break:break-word;
}
.msg-row.bot .msg-bubble{background:var(--bg2);border:1px solid var(--border);border-top-left-radius:4px;color:var(--text)}
.msg-row.user .msg-bubble{background:var(--bg3);border:1px solid var(--border);border-top-right-radius:4px;color:var(--text)}
.msg-time{font-size:13px;color:var(--text3);padding:0 4px;margin-top:2px;align-self:flex-end}
.msg-row.user .msg-time{text-align:right}

