.comp-left{display:flex;gap:4px}
.comp-cbtn{width:32px;height:32px;border-radius:50%;background:var(--bg3);border:1px solid var(--border);color:var(--text2);cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:16px;transition:all .15s}
.comp-cbtn:hover{background:var(--bg4);color:var(--text)}
#send-btn{
  width:32px;height:32px;border-radius:50%;
  background:var(--accent);border:none;color:#ffffff;
  font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;
  transition:opacity .15s;flex-shrink:0
}
#send-btn:hover{opacity:.85}
#send-btn:disabled{opacity:.35;cursor:default}
